'use strict';
const $=s=>document.querySelector(s);
const fmt=(n,d=2)=>!Number.isFinite(Number(n))?'—':Number(n).toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=n=>'NT$ '+fmt(n,0);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function analysis(q){const h=q.history.map(x=>x.close);if(h.length<21)return {trend:'資料累積中',ma:NaN,vol:NaN,low:NaN,high:NaN};const last=h.at(-1),ma=h.slice(-20).reduce((a,b)=>a+b,0)/20;const rs=h.slice(1).map((x,i)=>Math.log(x/h[i])),mean=rs.reduce((a,b)=>a+b,0)/rs.length;const vol=Math.sqrt(rs.reduce((a,b)=>a+(b-mean)**2,0)/rs.length)*Math.sqrt(20);return {trend:last>ma*1.01?'偏多觀察':last<ma*.99?'謹慎觀察':'持續觀察',ma,vol,low:last*Math.exp(-vol),high:last*Math.exp(vol)};}
function execute(account,q,side,quantity,now=Date.now()){if(q.demo||q.dataKind==='daily'||q.tradable===false||!q.asOf||now/1000-q.asOf>900||q.asOf>now/1000+60)throw Error('僅接受 15 分鐘內的真實行情；請更新行情，或於交易時段再試。');if(!Number.isInteger(quantity)||quantity<1||quantity>1000000)throw Error('請輸入 1 到 1,000,000 的整數股數。');if(!['buy','sell'].includes(side)||!Number.isFinite(q.price)||q.price<=0)throw Error('交易資料無效。');const a=structuredClone(account),position=a.positions[q.symbol]||{quantity:0,cost:0},gross=q.price*quantity,fee=gross*.001425,tax=side==='sell'?gross*(q.symbol.startsWith('00')?.001:.003):0;if(side==='buy'){if(gross+fee>a.cash)throw Error('可用虛擬資金不足。');a.cash-=gross+fee;position.cost+=gross+fee;position.quantity+=quantity;}else{if(position.quantity<quantity)throw Error('持有股數不足，不能賣出。');const cost=position.cost/position.quantity*quantity;position.cost-=cost;position.quantity-=quantity;a.cash+=gross-fee-tax;a.realized+=gross-fee-tax-cost;}if(position.quantity)a.positions[q.symbol]=position;else delete a.positions[q.symbol];a.trades.unshift({symbol:q.symbol,name:q.name,side,quantity,price:q.price,fee,tax,time:now});return a;}
if(typeof module!=='undefined')module.exports={analysis,execute};
