function renderDetail(){const q=quotes.find(q=>q.symbol===selected),a=analysis(q);renderPlain(q);$('#detail-name').textContent=q.name+' '+q.symbol;$('#detail-price').textContent=fmt(q.price);$('#detail-change').className=q.change>=0?'up':'down';$('#detail-change').textContent=(q.change>=0?'上漲 +':'下跌 ')+fmt(q.change)+'%';$('#detail-source').textContent=q.demo?'示範資料・非目前行情':q.source;$('#chart').innerHTML=spark(q.history,true);$('#chart-range').textContent=fmt(Math.min(...q.history.slice(-60).map(x=>x.close)),0)+' — '+fmt(Math.max(...q.history.slice(-60).map(x=>x.close)),0);$('#insights').innerHTML=`<div class="insight"><small>研究優先程度</small><strong class="up">${a.trend}</strong><p>最新收盤相對 20 日均線 ${fmt(a.ma)}，以 ±1% 為觀察門檻。不是買賣指令。</p></div><div class="insight"><small>20 日波動情境</small><strong>${fmt(a.low,0)} — ${fmt(a.high,0)}</strong><p>歷史日對數報酬波動換算，無上漲機率或獲利保證，實際可能超出範圍。</p></div><div class="insight"><small>新手下一步</small><strong>${!Number.isFinite(a.vol)?'等待至少 21 筆收盤資料':a.vol>.12?'先理解高波動':'分批研究，控制部位'}</strong><p>先看公司財報、重大訊息與資金需求，再用虛擬交易驗證想法。</p></div>`;$('#asof').textContent=q.demo?'此價格與圖表為固定示範，不能用於交易或判斷目前市場。':`行情時間：${new Date(q.asOf*1000).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'})}（臺北） · 日收盤資料（時間以臺北 13:30 標示），不是逐筆成交時間，快速虛擬練習採已發布收盤，不是盤中即時成交。${q.sync?.error?'最近同步失敗，保留先前資料。':''}`;}
