async function readPublishedBrief(){
 const [qr,ar]=await Promise.all([fetch(window.STOCKROOM_STATIC?'./data/quotes.json':'/api/quotes',{cache:'no-store',signal:AbortSignal.timeout(15000)}),fetch(window.STOCKROOM_STATIC?'./data/ai.json':'/api/ai',{cache:'no-store',signal:AbortSignal.timeout(15000)})]);
 if(!qr.ok||!ar.ok)throw Error('已發布解讀暫時無法讀取');const qs=(await qr.json()).quotes||[],reports=(await ar.json()).reports||[];
 const items=reports.filter(a=>a.status==='ready'&&Number.isFinite(Date.parse(a.generatedAt))&&Date.parse(a.generatedAt)<=Date.now()&&Date.now()-Date.parse(a.generatedAt)<7*86400000&&['summary','risks','checks'].every(k=>typeof a[k]==='string'&&a[k].trim())&&qs.some(q=>q.symbol===a.symbol&&q.asOf===a.asOf&&StockroomDecision.assess(q).ready));
 if(!items.length)throw Error('目前沒有日期匹配的已發布 AI 解讀');return items;
}
