async function openAI(symbol){
 aiDialogSymbol=symbol;const version=++aiDialogVersion;
 const item=catalogItems.find(x=>x.symbol===symbol)||quotes.find(x=>x.symbol===symbol);
 if(!item)return;
 $('#ai-title').textContent=`${item.name} ${symbol} · AI 解析`;
 $('#ai-copy').textContent=`複製 ${symbol}`;
 if(!$('#ai-dialog').open)$('#ai-dialog').showModal();
 $('#ai-dialog-body').textContent='正在讀取已生成的報告…';$('#ai-generate-status').textContent='';
 const q=quotes.find(x=>x.symbol===symbol),scheduled=aiReports.find(x=>x.symbol===symbol&&x.asOf===q?.asOf&&x.status==='ready');
 if(scheduled)$('#ai-dialog-body').innerHTML=aiHTML(scheduled);
 let data=null;
 try{
  const response=await fetch('https://raw.githubusercontent.com/timo893131/stock-analysis/ai-research/reports/'+encodeURIComponent(symbol)+'.json',{cache:'no-store',signal:AbortSignal.timeout(10000)});
  if(response.ok){const value=await response.json();if(value.quote?.symbol===symbol&&value.ai?.symbol===symbol&&value.ai?.status==='ready'&&value.ai.asOf===value.quote.asOf&&['summary','risks','checks'].every(k=>typeof value.ai[k]==='string'))data=value;}
 }catch{}
 if(version!==aiDialogVersion)return;
 if(scheduled&&(!data||Date.parse(scheduled.generatedAt)>Date.parse(data.ai.generatedAt)))data={quote:q,ai:scheduled};
 if(!data){$('#ai-dialog-body').innerHTML='<p>這檔股票尚未有可讀取的 AI 報告。按「一鍵 AI 解析」取得日收盤研究；若額度用完，可先查看走勢與財報，明日再試。</p>';return;}
 aiReports=aiReports.filter(x=>x.symbol!==symbol);aiReports.push(data.ai);
 const current=StockroomDecision.assess(data.quote);
 $('#ai-dialog-body').innerHTML=`<p class="${current.ready?'':'financial-warning'}">行情日 ${esc(data.quote.tradeDate||'未提供')} · ${current.ready?'日收盤研究，非即時報價':'資料過期或不足：以下僅供回顧，請先重新解析'}</p>`+aiHTML(data.ai,data.quote);
}
$('#ai-dialog').addEventListener('close',()=>{aiDialogVersion++;});$('#ai-open').onclick=async()=>{const symbol=selected;await openAI(symbol);if(!$('#ai-dialog').open||aiDialogSymbol!==symbol)return;const q=quotes.find(q=>q.symbol===symbol),ai=aiReports.find(a=>a.symbol===symbol&&a.asOf===q?.asOf),a=StockroomDecision.advice(q,ai);if(a.action==='insufficient'||a.action==='consider'&&![5,10,20,25].includes(ai?.allocationPct))$('#ai-generate').click();};$('#ai-close').onclick=()=>{$('#ai-dialog').close();aiDialogVersion++;};$('#ai-reload').onclick=()=>openAI(aiDialogSymbol);$('#ai-copy').onclick=async()=>{try{await navigator.clipboard.writeText(aiDialogSymbol);toast('已複製 '+aiDialogSymbol+'；請貼入 GitHub 的 symbol 欄位。');}catch{toast('請手動複製標題代碼：'+aiDialogSymbol);}};
$('#ai-generate').onclick=async()=>{const symbol=aiDialogSymbol,version=++aiDialogVersion;$('#ai-generate').disabled=true;$('#ai-generate-status').textContent='正在取得資料並解析，可能需要一至兩分鐘；請勿重複點擊。';try{const data=await requestStock(symbol,true);if(aiDialogVersion===version){$('#ai-dialog-body').innerHTML=`<p>行情日 ${esc(data.quote.tradeDate)}</p>`+aiHTML(data.ai,data.quote);$('#ai-generate-status').textContent='解析完成，可關閉視窗後查看行情與練習。';selected=symbol;render();}}catch(e){if(aiDialogVersion===version)$('#ai-generate-status').textContent=e.message;}finally{$('#ai-generate').disabled=false;}};
function renderDecision(){
 const q=quotes.find(x=>x.symbol===selected),a=StockroomDecision.assess(q);
 $('#decision-outlook').innerHTML=`<div class="decision-outlook" data-state="${!a.ready?'unavailable':a.label==='可列入小額研究'?'positive':'caution'}"><span class="tag">規則分析 · 不是 AI</span><h3>${esc(a.label)}</h3><p>${esc(a.reason)}</p>${a.ready?`<p>20 日均線 ${fmt(a.ma20)} · 60 日均線 ${fmt(a.ma60)} · 距月線 ${fmt(a.distance*100)}% · 資料日 ${esc(q.tradeDate||StockroomPaper.day(q.asOf*1000))}</p>`:''}</div>`;
 const ai=aiReports.find(x=>x.symbol===selected&&x.asOf===q.asOf&&x.status==='ready');
 $('#ai-explanation').innerHTML=ai?aiHTML(ai):'<p>目前沒有這檔的 AI 解讀。可以按上方按鈕嘗試，或先看規則說明與財報；沒有解讀不代表這檔股票不好。</p>';
 calculateSize();
}
function calculateSize(){const q=quotes.find(x=>x.symbol===selected),a=StockroomDecision.assess(q);if(!a.ready){$('#size-results').innerHTML='<p>真實資料就緒後才提供金額試算。</p>';return;}try{const r=StockroomDecision.size(q,{budget:Number($('#size-budget').value),riskPct:Number($('#size-risk').value),stopPct:Number($('#size-stop').value),capPct:Number($('#size-cap').value)});$('#size-results').innerHTML=`<div class="insight-grid"><div class="insight"><small>條件式部位上限</small><strong>${r.shares} 股 · ${money(r.cost)}</strong><p>金額含買入費用與 0.1% 滑價假設，不代表建議立即買入。</p></div><div class="insight"><small>假設停損價格</small><strong>${fmt(r.stop)}</strong><p>不是自動停損單，沒有保證可在此價成交。</p></div><div class="insight"><small>模型估計損失</small><strong>${money(r.loss)}</strong><p>設定可承受 ${money(r.riskBudget)}；含雙向費稅與滑價假設。</p></div></div><p>${a.label==='可列入小額研究'?'趨勢條件偏多，仍需查核財報、估值與分散風險。':'目前規則偏向觀察。上述金額只是「若決定交易」的上限，不是現在應買入的金額。'}</p>`;}catch(error){$('#size-results').textContent=error.message;}}
$('#size-form').onsubmit=e=>{e.preventDefault();calculateSize();};document.querySelectorAll('#size-form input').forEach(x=>x.oninput=calculateSize);$('#use-paper-budget').onclick=()=>{$('#size-budget').value=Math.floor(account.cash-StockroomPaper.reserves(account).cash);calculateSize();};$('#jump-decision').onclick=()=>$('#decision-panel').scrollIntoView({behavior:'smooth'});
