function renderBacktest(){
 const q=quotes.find(x=>x.symbol===selected),target=$('#backtest-results');
 const date=t=>new Date(t*1000).toLocaleDateString('zh-TW',{timeZone:'Asia/Taipei'});
 try{
  const r=StockroomBacktest.run(q.history,{period:Number($('#bt-period').value),allocation:Number($('#bt-allocation').value),etf:q.symbol.startsWith('00'),bond:/^00\d+[A-Z]?B\.(TW|TWO)$/.test(q.symbol)}),s=r.strategy,b=r.benchmark;
  const points=s.curve.concat(b.curve).map(x=>x.equity),lo=Math.min(r.initial,...points),hi=Math.max(r.initial,...points),range=hi-lo||1;
  const line=c=>c.map((x,i)=>`${i*660/Math.max(1,c.length-1)+20},${155-(x.equity-lo)/range*130}`).join(' ');
  target.innerHTML=`<div class="banner ${q.demo?'':'live'}">${q.demo?'示範資料回測：以下結果不代表任何股票的真實績效。':'真實歷史收盤資料回測：未調整股利與拆股，不代表總報酬。'}</div>
  <p>${esc(q.name)} · ${date(r.start)} — ${date(r.end)} · ${r.bars} 筆評估資料 · 起始資金 ${money(r.initial)}</p>
  <div class="insight-grid"><div class="insight"><small>策略淨報酬</small><strong class="${s.totalReturn>=0?'up':'down'}">${fmt(s.totalReturn*100)}%</strong><p>期末 ${money(s.finalEquity)}，已扣費用與模擬滑價。</p></div><div class="insight"><small>最大回撤</small><strong class="down">${fmt(s.maxDrawdown*100)}%</strong><p>帳戶曾從高點跌落多少；越大越考驗持有耐心。</p></div><div class="insight"><small>同部位買入持有</small><strong>${fmt(b.totalReturn*100)}%</strong><p>策略差距 ${fmt((s.totalReturn-b.totalReturn)*100)} 個百分點。</p></div></div>
  <div class="backtest-legend"><span>● 均線策略</span><span>● 同部位買入持有</span></div>
  <svg class="backtest-chart" viewBox="0 0 700 180" role="img" aria-label="均線策略與同部位買入持有的帳戶價值比較"><polyline points="${line(b.curve)}" fill="none" stroke="#b0a38b" stroke-width="2"/><polyline points="${line(s.curve)}" fill="none" stroke="#15846d" stroke-width="2"/></svg>
  <p>完成 ${s.roundTrips} 次買賣 · 勝率 ${s.winRate===null?'不適用':fmt(s.winRate*100)+'%'} · 手續費與稅 ${money(s.fees)}（滑價另反映於成交價）</p>
  <div class="backtest-note">${s.roundTrips<10?'樣本偏少：少量交易的勝率容易失真，不宜據此判斷未來表現。':'這是同一段歷史的回顧，尚未做獨立樣本外驗證。'} ${q.demo?'請先啟用真實行情，再評估策略。':'如有拆股或除權息，未調整價格可能扭曲報酬。'}</div>
  <details><summary>看懂規則、成本與限制</summary><p>收盤高於 ${r.period} 日均線 1% 時產生買入訊號，低於均線 1% 時產生賣出訊號；使用下一筆交易日收盤價模擬成交，不在訊號當天成交。一次只持有一筆部位，不借款。買入持有基準於同一評估起日投入相同比例資金，剩餘現金不計息。</p><p>雙向手續費 0.1425%，賣出稅 ${r.bond?'債券 ETF 至 2026 年底免徵，之後模型採 0.1%':fmt(r.taxRate*100,1)+'%'}，雙向不利滑價 0.1%；未模擬最低手續費、漲跌停、停牌或成交量限制。期末以最後收盤價扣成本結算，並不是即時可執行委託。沒有股利再投入、拆股調整或預測能力驗證。調整參數後挑最好結果會產生過度擬合。</p></details>
  <details><summary>查看 ${s.trades.length} 筆模擬成交</summary><div class="table-wrap"><table><thead><tr><th>訊號日</th><th>成交日</th><th>方向 / 原因</th><th>股數</th><th>含滑價價格</th><th>費稅</th></tr></thead><tbody>${s.trades.map(t=>`<tr><td>${t.signalTime?date(t.signalTime):'—'}</td><td>${date(t.time)}</td><td>${t.side==='buy'?'買入':'賣出'} · ${t.reason}</td><td>${t.quantity}</td><td>${fmt(t.price)}</td><td>${fmt(t.fee+t.tax)}</td></tr>`).join('')||'<tr><td colspan="6">此區間沒有觸發可成交的訊號。</td></tr>'}</tbody></table></div></details>`;
 }catch(error){target.innerHTML=`<div class="banner" data-state="caution">${esc(error.message)} 請選較短均線，或等待更多行情資料。</div>`;}
}
