const viewSelectors={overview:'#home-view',market:'#overview-view',detail:'#detail-view',portfolio:'#portfolio-view',settings:'#settings-view',learn:'#learn-view'};
let detailTab='chart';
function switchTab(next,updateURL=true){
 if(next==='watch')next='market';if(!viewSelectors[next])next='overview';tab=next;document.body.dataset.view=next;
 const names={overview:'總覽',market:'找股票',detail:'個股分析',portfolio:'虛擬投資',settings:'設定',learn:'新手指南'};
 const descriptions={overview:'先看今日研究重點，再決定下一步。',market:'輸入股票名稱或代碼，收藏、分析與練習。',detail:'一次查看一類資訊，需要時再深入。',portfolio:'用虛擬資金練習，追蹤持倉與委託。',settings:'服務狀態與使用說明，集中在這裡。',learn:'從行情時間、風險與交易成本開始。'};
 for(const [key,selector] of Object.entries(viewSelectors))$(selector).classList.toggle('hidden',key!==next);
 document.querySelectorAll('.nav').forEach(x=>{const active=x.dataset.tab===(next==='detail'?'market':next==='learn'?'settings':next);x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current');});
 $('#breadcrumb').textContent=names[next];$('#page-title').textContent=names[next];$('#page-description').textContent=descriptions[next];$('#status-guide').classList.toggle('hidden',next==='learn');$('#refresh').classList.toggle('hidden',['settings','learn'].includes(next));$('#data-banner').classList.toggle('hidden',['settings','learn'].includes(next));
 if(updateURL&&location.hash!=='#'+next)history.pushState(null,'','#'+next);
 render();StockroomShell.route(next,next==='detail'?(quotes.find(q=>q.symbol===selected)?.name||names[next]):names[next],next==='detail'?selected:null);if(next==='portfolio')void syncPaperData(true);window.scrollTo({top:0,behavior:'auto'});
}
function showDetail(part='chart'){persist('stockroom-last-seen',selected);detailTab=part;switchTab('detail');const panels={chart:'#stock-detail',decision:'#decision-panel',financial:'.financial-panel',backtest:'#backtest-panel',news:'#news-panel',plan:'#plan-panel'};for(const [name,selector] of Object.entries(panels))$(selector)?.classList.toggle('hidden',name!==part);document.querySelectorAll('[data-detail-tab]').forEach(b=>{const active=b.dataset.detailTab===part;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}
function setupMenus(){
 const page=$('.page'),home=document.createElement('div'),settings=document.createElement('div'),detail=document.createElement('section');home.id='home-view';settings.id='settings-view';detail.id='detail-view';settings.className=detail.className='hidden';
 page.insertBefore(home,$('#api-settings'));page.insertBefore(settings,$('#overview-view'));page.insertBefore(detail,$('#portfolio-view'));
 home.innerHTML='<div class="menu-shortcuts"><button class="outline" data-go="portfolio">▣ 我的虛擬練習</button></div>';home.querySelector('.menu-shortcuts').prepend($('#brief-run'));
 const coach=document.createElement('section');coach.id='beginner-coach';coach.className='panel beginner-coach';home.prepend(coach);const fullLink=document.createElement('button');fullLink.className='outline full-market-teaser';fullLink.id='full-market-teaser';fullLink.textContent='查看全市場收盤行情';fullLink.onclick=()=>{switchTab('market');StockroomMarketUI.setMode('all');};home.append(fullLink);home.append($('#quick-panel'));const marketMore=document.createElement('details');marketMore.className='market-more';marketMore.innerHTML='<summary>查看重點行情數字</summary>';marketMore.append($('#market-cards'));home.append(marketMore);
 $('.filters').after($('.stock-panel .search'));
 settings.append($('#api-settings'));const help=document.createElement('section');help.className='panel';help.innerHTML='<h2>使用說明</h2><p>搜尋股票 → 查看走勢或 AI → 虛擬練習。進階財報與回測在個股選單中。</p><button class="outline" data-go="learn">開啟新手指南</button>';settings.append(help);
 const advanced=document.createElement('details');advanced.className='manual-sizing';advanced.innerHTML='<summary>進階：自己設定風險與部位上限</summary><p>這是獨立公式工具，與上方 AI 第一筆小額試算分開。調整條件會改變計算上限。</p>';const manualNote=$('#size-results').nextElementSibling;advanced.append($('#decision-outlook'),$('#size-form'),$('#size-results'),manualNote);$('#decision-panel').append(advanced);
 const detailGuide=document.createElement('p');detailGuide.className='view-guide';detailGuide.textContent='先看走勢 → AI 與金額 → 核對財報／消息 → 虛擬練習；回測可檢查歷史策略。';detail.append(detailGuide);
 const back=document.createElement('button');back.className='outline back-to-stocks';back.textContent='← 返回找股票';back.onclick=()=>switchTab('market');detail.append(back,$('#stock-detail .panel-heading'));
 const actions=$('.detail-actions');const chart=document.createElement('button');chart.className='outline';chart.textContent='走勢';chart.id='jump-chart';actions.prepend(chart);actions.setAttribute('aria-label','個股分析分類');detail.append(actions);
 $('#news').closest('section').id='news-panel';for(const selector of ['#stock-detail','#decision-panel','.financial-panel','#backtest-panel','#news-panel'])detail.append($(selector));
 for(const [id,part] of Object.entries({'jump-chart':'chart','jump-decision':'decision','jump-financial':'financial','jump-backtest':'backtest','jump-news':'news'})){const b=$('#'+id);b.dataset.detailTab=part;b.onclick=()=>showDetail(part);}
 document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>switchTab(b.dataset.go));
 $('.brand').onclick=e=>{e.preventDefault();switchTab('overview');};
 const route=()=>{const hash=location.hash.slice(1);if(hash==='detail')showDetail(detailTab);else switchTab(hash==='api-settings'?'settings':hash,false);};window.addEventListener('popstate',route);window.addEventListener('hashchange',()=>{if(location.hash==='#learn'&&$('#ai-dialog').open)$('#ai-dialog').close();route();});route();
}

function savePaper(next){
 if(paperLocked){toast('練習資料無法讀取，請先匯出原始備份。');return false;}
 try{if(localStorage.getItem(PAPER_KEY)!==paperStored){loadPaper();render();toast('其他分頁已更新帳戶，已重新讀取，請重試。');return false;}StockroomPaper.validate(next);const raw=JSON.stringify(next);localStorage.setItem(PAPER_KEY,raw);paperStored=raw;account=next;return true;}catch(error){toast('無法儲存：'+error.message);return false;}
}
function loadPaper(){
 try{paperStored=localStorage.getItem(PAPER_KEY);account=paperStored?StockroomPaper.validate(JSON.parse(paperStored)):StockroomPaper.fresh();paperLocked=false;}catch{paperLocked=true;account=StockroomPaper.fresh();}
}
function reconcilePaper(){if(paperLocked||StockroomShell.offline)return;const next=StockroomPaper.settle(account,quotes);if(JSON.stringify(next)!==JSON.stringify(account)){const filled=next.trades.length-account.trades.length;if(savePaper(next))toast(filled?`已依新的收盤行情結算 ${filled} 筆練習交易。`:'待成交委託狀態已更新。');}}
async function syncPaperData(automatic=false){
 if(StockroomShell.offline){paperSyncMessage='目前離線或資料連線異常，已暫停結算；恢復連線後可按更新並結算。';if(tab==='portfolio')renderPortfolio();return;}
 if(paperLocked||paperSyncBusy||automatic&&!paperBaseReady)return;
 if(automatic&&paperAutoCount>=5)return;
 paperSyncBusy=true;const beforeTrades=account.trades.length,beforeExpired=account.orders.filter(o=>o.status==='expired').length;let count=0;
 try{
  if(!automatic){paperSyncMessage='正在讀取每日行情與全市場來源，接著檢查委託…';if(tab==='portfolio')renderPortfolio();await refresh();await StockroomMarketUI.reload();}
  reconcilePaper();const needed=StockroomPaper.syncTargets(account,quotes,StockroomMarketUI.getQuotes());
  const targets=needed.filter(s=>!automatic||Date.now()-(paperSyncAttempts.get(s)||0)>15*60000).sort((a,b)=>(paperSyncAttempts.get(a)||0)-(paperSyncAttempts.get(b)||0)).slice(0,automatic?5-paperAutoCount:5);
  for(const symbol of targets){
   paperSyncAttempts.set(symbol,Date.now());if(automatic)paperAutoCount++;paperSyncMessage=`正在補載 ${symbol} 的完整歷史（${count+1}/${targets.length}），只檢查結算，不呼叫 AI。`;if(tab==='portfolio')renderPortfolio();
   try{await requestStock(symbol,false);count++;paperSyncErrors.delete(symbol);if(StockroomPaper.syncTargets(account,quotes,StockroomMarketUI.getQuotes()).includes(symbol))paperSyncErrors.set(symbol,'來源歷史尚未追上所需收盤日，已保留委託；稍後更新再檢查。');}
   catch(error){paperSyncErrors.set(symbol,error.message);if(/額度/.test(error.message))break;}
  }
  reconcilePaper();const remaining=StockroomPaper.syncTargets(account,quotes,StockroomMarketUI.getQuotes()).length,filled=account.trades.length-beforeTrades,expired=account.orders.filter(o=>o.status==='expired').length-beforeExpired;
  paperSyncMessage=`本次補載 ${count} 檔；新增成交 ${filled} 筆、未成交 ${expired} 筆。${remaining?`仍有 ${remaining} 檔待補資料，請看下方原因；一次最多補載 5 檔，可按更新繼續。`:'委託已檢查；尚未到後續收盤日的委託會保留等待。'}`;
 }catch(error){paperSyncMessage='結算檢查未完成：'+error.message;}
 finally{paperSyncBusy=false;if(tab==='portfolio')renderPortfolio();}
}
function paperOrderInfo(o,marketDates){
 const info=StockroomPaper.pendingInfo(o,quotes.find(q=>q.symbol===o.symbol),marketDates.get(o.symbol));
 if(o.status!=='expired')return `<p class="paper-order-detail">${esc(info.reason)}</p>${o.status==='pending'&&paperSyncErrors.has(o.symbol)?`<p class="paper-data-error">補載提示：${esc(paperSyncErrors.get(o.symbol))}</p>`:''}`;
 const price=Number.isFinite(o.evaluatedPrice)&&o.evaluatedPrice>0?o.evaluatedPrice:null,priceRejected=price&&(o.side==='buy'?price>o.limit:price<o.limit),date=Number.isFinite(o.evaluatedAt)?StockroomPaper.day(o.evaluatedAt):null;
 return `<section class="paper-outcome" aria-label="未成交說明"><h3>${priceRejected?(o.side==='buy'?'價格超過你的最高買價':'價格低於你的最低賣價'):'本次委託未成交'}</h3><p>${o.side==='buy'?'這筆沒有扣款，預留資金已釋放。':'這筆沒有賣出持股，預留股數已釋放。'}不會自動再次送單。</p>${priceRejected?`<dl class="paper-price-compare"><div><dt>你設定的${o.side==='buy'?'最高買價':'最低賣價'}</dt><dd>NT$ ${fmt(o.limit)}</dd></div><div><dt>${esc(date||'結算日')} 試算價（含滑價）</dt><dd>NT$ ${fmt(price)}</dd></div></dl><p class="fine-print">每股${o.side==='buy'?'超出':'低於'} NT$ ${fmt(Math.abs(price-o.limit))}（${fmt(Math.abs(price/o.limit-1)*100)}%），所以這次沒有${o.side==='buy'?'買入':'賣出'}。</p>`:''}<details><summary>查看原始結算說明</summary><p>${esc(info.reason)}</p></details></section>`;
}
async function retryPaper(id){
 if(paperRetryBusy)return;
 if(StockroomShell.offline)return toast('恢復連線後才能重新試算委託。');
 if(paperLocked)return toast('帳戶資料無法讀取，請先匯出備份。');
 const o=account.orders.find(o=>o.id===id&&o.status==='expired');if(!o)return;
 if(account.orders.some(x=>x.symbol===o.symbol&&x.status==='pending'))return toast('這檔已有待成交委託，請先查看等待原因。');
 paperRetryBusy=true;paperSyncMessage='正在準備 '+o.name+' 的重新試算，只開啟草稿、不會送單…';renderPortfolio();
 try{
  const q=quotes.find(q=>q.symbol===o.symbol),snapshot=StockroomMarketUI.getQuotes().find(q=>q.symbol===o.symbol),valid=q?.demo===false&&q.dataKind==='daily'&&!q.sync?.error&&Number.isFinite(q.price)&&q.price>0&&Number.isFinite(q.asOf)&&q.asOf*1000<=Date.now()&&Date.now()-q.asOf*1000<=7*86400000;
  if(!valid||snapshot?.tradeDate>StockroomPaper.day(q.asOf*1000))await requestStock(o.symbol,false);
  if(StockroomShell.offline)throw Error('目前連線中斷，請恢復連線後再試。');
  const latest=quotes.find(q=>q.symbol===o.symbol);if(snapshot?.tradeDate>StockroomPaper.day(latest.asOf*1000))throw Error('歷史行情尚未追上已發布收盤日，請稍後更新再試。');
  if(paperLocked)throw Error('帳戶資料無法讀取，請先匯出備份。');
  if($('#trade-dialog').open)throw Error('另一張委託草稿已開啟，請先完成或關閉。');
  if(account.orders.some(x=>x.symbol===o.symbol&&x.status==='pending'))throw Error('這檔已新增待成交委託，未重複開啟草稿。');
  openPaper(o.side,o.symbol,'next-close');$('#quantity').value=o.quantity;$('#order-note').value=o.note;$('#trade-info').textContent+=' 這是重新試算草稿：保留原股數與理由，價格已重設為本次參考收盤的'+(o.side==='buy'?'102%':'98%')+'，可自行調整，不代表建議追價。確認後才會建立新的委託。';updateEstimate();paperSyncMessage='已開啟重新試算草稿；原紀錄保留，尚未送出新委託。';
 }catch(error){paperSyncMessage='重新試算未完成：'+error.message;toast(paperSyncMessage);}
 finally{paperRetryBusy=false;renderPortfolio();}
}
function renderPortfolio(){
 const pendingCount=account.orders.filter(o=>o.status==='pending').length;
 const reserved=StockroomPaper.reserves(account),marketDates=new Map(StockroomMarketUI.getQuotes().map(q=>[q.symbol,q.tradeDate]));let total=account.cash,unrealized=0,missing=false;
 const positionCards=Object.entries(account.positions).map(([symbol,p])=>{const q=quotes.find(x=>x.symbol===symbol),valid=q&&!q.demo&&!q.sync?.error&&Number.isFinite(q.price)&&q.price>0&&Number.isFinite(q.asOf)&&q.asOf*1000<=Date.now()&&Date.now()-q.asOf*1000<=7*86400000;if(!valid)missing=true;const value=valid?q.price*p.quantity:null;if(valid){total+=value;unrealized+=value-p.cost;}return `<article class="holding-card"><div class="panel-heading"><h3>${esc(q?.name||symbol)} <small>${esc(symbol)}</small></h3><span>${p.quantity} 股</span></div><div class="holding-numbers"><div><small>平均成本（含費用）</small><strong>${fmt(p.cost/p.quantity)}</strong></div><div><small>未實現損益</small><strong class="${valid&&value-p.cost>=0?'up':'down'}">${valid?money(value-p.cost):'待行情'}</strong></div><div><small>持倉市值</small><strong>${valid?money(value):'待行情'}</strong></div></div><p>行情：${valid?new Date(q.asOf*1000).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}):'尚未取得'} · 已預留賣出 ${reserved.shares[symbol]||0} 股</p><button class="outline" data-paper-sell="${symbol}">練習賣出</button><button class="outline" data-paper-research="${symbol}">查看分析</button></article>`;}).join('');
 const invested=StockroomPaper.capital(account),added=invested-account.initial;
 const expiredCount=account.orders.filter(o=>o.status==='expired').length,filledCount=account.orders.filter(o=>o.status==='filled').length;
 $('#portfolio-view').innerHTML=`<div class="panel-heading"><div><h2>我的虛擬練習</h2></div><div class="practice-header-actions"><button class="outline" id="paper-plan" type="button">進階風險計畫</button><button class="green-button compact" id="paper-new">＋ 輸入金額買入</button></div></div>${paperLocked?'<div class="banner" data-state="caution">既有帳戶資料無法讀取。已暫停下單與寫入，下方數字不是已還原的持倉；請先匯出原始資料。</div>':''}<details class="paper-rules"><summary>練習方式與舊委託規則</summary><div class="banner">自由練習：按你輸入的完整金額換算股數，用已取得收盤價建立虛擬持倉。沒有固定 100 萬額度；不足時追加有紀錄的虛擬資金，不算收益。舊的待成交委託仍依下一交易日收盤規則檢查。</div></details><div class="paper-sync-box"><button class="outline" id="paper-sync" type="button" ${paperSyncBusy||!paperBaseReady?'disabled':''}>${paperSyncBusy?'正在檢查結算…':'⟳ 更新並結算委託'}</button><p id="paper-sync-status" role="status">${esc(paperSyncMessage||(!paperBaseReady?'正在讀取每日行情…':'會優先補載待成交與持倉股票，每次最多 5 檔；不呼叫 AI。'))}</p></div><div class="market-grid"><div class="market-card"><p>帳戶估值（含現金）</p><strong>${missing?'待行情':money(total)}</strong><span class="change">累計淨盈虧 ${missing?'—':money(total-invested)}（已扣追加資金）</span></div><div class="market-card"><p>練習額度</p><strong>自由投入</strong><span class="change">現有可用 ${money(account.cash-reserved.cash)}；不足可追加</span></div><div class="market-card"><p>已實現損益</p><strong>${money(account.realized)}</strong><span class="change">未實現 ${missing?'待行情':money(unrealized)}</span></div></div><p class="funding-summary">累計投入 ${money(invested)}（原始 ${money(account.initial)}＋追加 ${money(added)}）。追加不是獲利，賣出也不會重設本金。</p><div class="practice-steps"><span>① 輸入金額</span><span>② 確認股數與費用</span><span>③ 查看持倉</span></div><div class="paper-status-summary" aria-label="委託結果總覽"><span>等待檢查 <b>${pendingCount}</b></span><span>已成交 <b>${filledCount}</b></span><span>未成交 <b>${expiredCount}</b></span></div><h2>目前持倉</h2><div class="holding-grid">${positionCards||(pendingCount?`<div class="empty"><b>有 ${pendingCount} 筆委託等待檢查，尚未形成持倉。</b><p>請看下方每筆委託的等待日期或資料提示；不用重新下相同委託。</p><button class="outline" id="paper-pending-link">查看等待原因 ↓</button></div>`:`<div class="empty"><b>${expiredCount?'已有 '+expiredCount+' 筆委託未成交，因此沒有新增持倉。':'目前沒有持倉。'}</b><p>${expiredCount?'未成交的買入沒有扣款；下方可查看原因，或重新試算一筆新委託。':'可查看委託結果與成交紀錄，或選股票開始虛擬練習。'}</p><button class="outline" id="paper-browse">探索股票</button></div>`)}</div><h2 id="paper-orders-title">委託紀錄</h2><div class="order-list">${account.orders.slice(0,100).map(o=>`<article class="order-card" data-state="${o.status==='pending'?'caution':o.status==='filled'?'info':'unavailable'}"><div><b>${esc(o.name)} · ${o.side==='buy'?'買入':'賣出'} ${o.quantity} 股</b><span class="tag">${StockroomPaper.pendingInfo(o,quotes.find(q=>q.symbol===o.symbol),marketDates.get(o.symbol)).label}</span></div><p>${o.side==='buy'?'最高買價':'最低賣價'} ${fmt(o.limit)} · 建立於 ${esc(new Date(o.createdAt).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}))}</p>${o.note?`<p class="order-note">理由：${esc(o.note)}</p>`:''}${paperOrderInfo(o,marketDates)}${o.status==='pending'?`<button class="outline" data-paper-cancel="${esc(o.id)}">取消委託</button>`:o.status==='expired'?`<button class="outline" data-paper-retry="${esc(o.id)}" ${paperRetryBusy||paperLocked||account.orders.some(x=>x.symbol===o.symbol&&x.status==='pending')?'disabled':''}>${account.orders.some(x=>x.symbol===o.symbol&&x.status==='pending')?'已有委託等待檢查':paperRetryBusy?'正在準備試算…':'依已取得行情重新試算'}</button>`:''}</article>`).join('')||'<p class="empty">尚未送出委託</p>'}</div><details class="trade-history"><summary>成交紀錄（最近 100 筆）</summary><div class="table-wrap"><table><thead><tr><th>成交日</th><th>股票</th><th>方向</th><th>股數</th><th>含滑價價格</th><th>費稅</th></tr></thead><tbody>${account.trades.slice(0,100).map(t=>`<tr><td>${esc(StockroomPaper.day(t.time))}${t.priceAsOf?`<small>用 ${esc(StockroomPaper.day(t.priceAsOf*1000))} 收盤練習</small>`:''}</td><td>${esc(t.name)}</td><td>${t.side==='buy'?'買入':'賣出'}</td><td>${t.quantity}</td><td>${fmt(t.price)}</td><td>${fmt(t.fee+t.tax)}</td></tr>`).join('')||'<tr><td colspan="6">尚無成交</td></tr>'}</tbody></table></div></details><details class="funding-history"><summary>查看追加虛擬資金紀錄（${(account.funding||[]).length} 筆）</summary><ul>${(account.funding||[]).slice(-20).reverse().map(f=>`<li>${esc(new Date(f.time).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}))}：追加 ${money(f.amount)}；只增加本金，不算收益。</li>`).join('')||'<li>尚未追加，仍沿用原始虛擬資金。</li>'}</ul></details><div class="backup-actions"><button class="outline" id="paper-export">下載帳戶備份</button><label class="outline">匯入備份<input id="paper-import" type="file" accept="application/json" hidden></label><button class="outline" id="reset-account">重設練習帳戶</button></div><p class="fine-print">資料只存在目前瀏覽器，換手機或清除網站資料會遺失，請定期備份。帳戶估值未預扣未來賣出成本；自由練習追加虛擬資金不計為收益。未處理股利、拆股或價格調整。原版練習帳戶仍保留在舊的本機儲存欄位，本版另用新版帳戶。</p>`;
 $('#paper-plan').onclick=()=>showDetail('plan');$('#paper-sync').onclick=()=>syncPaperData(false);$('#paper-pending-link')?.addEventListener('click',()=>$('#paper-orders-title').scrollIntoView({block:'start',behavior:'smooth'}));$('#paper-new').onclick=()=>openPaper('buy');$('#paper-browse')?.addEventListener('click',()=>switchTab('market'));
 $('#reset-account').onclick=()=>{if(confirm('清除新版帳戶的所有持倉與委託，回到 100 萬元？請先匯出備份。')){if(savePaper(StockroomPaper.fresh()))render();}};
 $('#paper-export').onclick=()=>{const url=URL.createObjectURL(new Blob([paperLocked?(paperStored||''):JSON.stringify(account,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='stockroom-paper-'+StockroomPaper.day(Date.now())+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $('#paper-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>3000000)throw Error('備份不能超過 3 MB。');const incoming=StockroomPaper.validate(JSON.parse(await file.text()));if(confirm('匯入會取代新版帳戶，是否已備份目前紀錄並確定繼續？')){if(savePaper(incoming)){reconcilePaper();render();}}}catch(error){toast('匯入失敗：'+error.message);}};
}
function openPaper(side='buy',symbol=selected,execution='known-close'){
 if(paperLocked)return toast('帳戶資料無法讀取，請先匯出備份。');const q=quotes.find(x=>x.symbol===symbol);if(!q){loadStock(symbol);return toast('請先載入行情，再開啟虛擬委託。');}
 selected=symbol;$('#paper-symbol').innerHTML=quotes.map(x=>`<option value="${x.symbol}">${esc(x.name)} ${x.symbol}</option>`).join('');$('#paper-symbol').value=symbol;$('#trade-title').textContent=q.name+' · 自由虛擬練習';$('#side').value=side;$('#paper-execution').value=execution;$('#paper-amount').value='';$('#quantity').value=1;$('#order-note').value='';$('#trade-error').textContent='';setPracticeMode();if(!$('#trade-dialog').open)$('#trade-dialog').showModal();
}
function setPracticeMode(){
 const q=quotes.find(x=>x.symbol===selected),side=$('#side').value,immediate=$('#paper-execution').value==='known-close';
 $('#limit-label').hidden=immediate;$('#order-limit').readOnly=immediate;$('#order-limit').value=(immediate?StockroomPaper.executionPrice(q,side):q.price*(side==='buy'?1.02:.98)).toFixed(2);$('#limit-label').firstChild.textContent=immediate?'試算每股價（已計不利滑價）':side==='buy'?'最高買價（每股）':'最低賣價（每股）';$('#paper-amount-label').hidden=side==='sell';
 $('#trade-info').textContent=(q.demo?'目前為示範資料，不能下單。':'價格依據 '+StockroomPaper.day(q.asOf*1000)+' 收盤 '+money(q.price)+'。')+(immediate?' 確認後直接更新虛擬持倉，不用等下一交易日；不是即時行情或真實交易。':' 這是進階委託，之後第一個交易日收盤只檢查一次，限價不符不成交。');
 $('#trade-form [type=submit]').textContent=immediate?(side==='buy'?'確認虛擬買入':'確認虛擬賣出'):'送出下一交易日委託';updateEstimate();
}
function updateEstimate(){
 const q=quotes.find(x=>x.symbol===selected),limit=Number($('#order-limit').value),side=$('#side').value,r=StockroomPaper.reserves(account),available=account.cash-r.cash;let quantity=Number($('#quantity').value),conversion=null;
 try{
  if(side==='buy'&&$('#paper-amount').value.trim()){conversion=StockroomPaper.amountShares(StockroomDecision.parseBudget($('#paper-amount').value),limit);quantity=conversion.shares;$('#quantity').value=quantity;}
  if(!Number.isSafeInteger(quantity)||quantity<0||!Number.isFinite(limit)||limit<=0)throw Error('請確認金額、股數與價格。');
  const gross=Math.round(quantity*limit*100)/100,cost=Math.round((gross+Math.round(gross*StockroomPaper.feeRate*100)/100)*100)/100,extra=Math.max(0,Math.round((cost-available)*100)/100),exact=n=>'NT$ '+fmt(n,2);
  $('#order-estimate').textContent=side==='buy'?`將買 ${quantity} 股，含費用 ${exact(cost)}。${conversion?'未使用金額 '+exact(conversion.left)+'。':''}${extra?'確認時補入 '+exact(extra)+' 虛擬資金（不算獲利）。':'不套用單檔比例或首筆折減。'}`:`將賣 ${quantity} 股；可賣 ${(account.positions[q.symbol]?.quantity||0)-(r.shares[q.symbol]||0)} 股。實際所得扣除費稅。`;
  $('#trade-error').textContent=conversion&&!quantity?'這筆金額不足買 1 股（含費用），請增加金額或選擇價格較低的標的。':'';
 }catch(error){if(side==='buy'&&$('#paper-amount').value.trim())$('#quantity').value=0;$('#order-estimate').textContent='尚未換算，沒有送出委託。';$('#trade-error').textContent=error.message;}
}
$('#portfolio-view').addEventListener('click',e=>{const cancel=e.target.closest('[data-paper-cancel]'),sell=e.target.closest('[data-paper-sell]'),research=e.target.closest('[data-paper-research]'),retry=e.target.closest('[data-paper-retry]');try{if(retry){void retryPaper(retry.dataset.paperRetry);return;}if(cancel&&savePaper(StockroomPaper.cancel(account,cancel.dataset.paperCancel)))render();if(sell)openPaper('sell',sell.dataset.paperSell);if(research){if(!quotes.some(q=>q.symbol===research.dataset.paperResearch)){switchTab('market');loadStock(research.dataset.paperResearch);return;}selected=research.dataset.paperResearch;switchTab('overview');showDetail();news();}}catch(error){toast(error.message);}});
$('#learn-view').innerHTML='<h2 style="margin-top:14px">你的第一份投資指南</h2>'+[['01 · 行情時間，比價格更重要','臺股一般交易時段為交易日 09:00–13:30（臺北時間）。盤後價格可能是最近一次成交，並非此刻可成交的價格。本網站以來源時間標示資料，快速練習用已取得的真實日收盤建立虛擬持倉；進階委託則在委託日之後第一筆交易日收盤檢查。'],['02 · 技術訊號怎麼看？','20 日均線是最近 20 個交易日收盤價的平均。價格高於均線 1% 標記偏多觀察，低於 1% 標記謹慎觀察，中間為持續觀察。這只是價格趨勢，沒有涵蓋估值、財報或新聞影響。'],['03 · 預計效果不是預言','波動情境使用最近約半年日對數報酬的標準差乘上 √20，再換算為價格範圍。這是歷史波動尺度，不是模型預測、信賴區間或保證報酬；極端事件可能讓價格超出範圍。'],['04 · 用虛擬交易培養紀律','原始虛擬資金 100 萬元，自由練習不足時可追加並記入本金，不當作獲利。每次買賣計入 0.1425% 手續費，賣出股票收取 0.3% 交易稅，股票型 ETF 為 0.1%；債券 ETF 依適用期間計算。新版練習另計雙向 0.1% 不利滑價，但未涵蓋券商最低費用、折扣、股利與拆股調整，因此不能視為真實績效。'],['05 · 找到可信資訊','先看公開資訊觀測站的財報與重大訊息，再交叉核對交易所資料與具名媒體。新聞標題可能過時或不完整，應開啟原文確認發佈時間與內容。'],['06 · 把風險放在報酬前面','避免以單一訊號投入所有資金。先記錄投資理由、可以承受的損失與檢查時間。虛擬交易無法重現真實金錢下的心理壓力，也不保證未來的結果。']].map(([h,p])=>`<details class="lesson"><summary>${h}</summary><p>${p}</p></details>`).join('');
const glossary=document.createElement('section');glossary.className='plain-glossary';glossary.innerHTML='<h3>看不懂的名詞，點一下</h3>'+[['MA20／20 日均線','最近 20 個交易日收盤價的平均，用來看價格相對於近期水準的位置；不是未來價格。'],['EPS／每股盈餘','公司每股分到多少盈餘。正值不代表股價便宜，還要看期間與估值。'],['ETF','把一籃子資產放在一檔商品裡。不同 ETF 風險差很多，仍要看持股與費用。'],['零股／一張','股票一般一張是 1,000 股；不足一張可用零股練習，本網站以「股」輸入。'],['停損','事先設定可接受的損失；本站的停損價只是試算，不會自動幫你賣出。'],['回測／最大回撤','回測用歷史資料模擬規則；最大回撤是期間中從高點到低點的最大跌幅，都不是未來獲利保證。']].map(([term,text])=>`<details><summary>${term}</summary><p>${text}</p></details>`).join('');$('#learn-view').append(glossary);
const quiz=document.createElement('section');quiz.className='learning-quiz';quiz.innerHTML='<h3>30 秒確認：進階的下一交易日委託會立即成交嗎？</h3><div class="quiz-options"><button class="outline" data-quiz="later">下一交易日收盤才檢查，價格條件不符會失效</button><button class="outline" data-quiz="now">按送出就會立刻成交</button></div><p id="quiz-answer" role="status"></p><button class="green-button compact" id="learn-start">看懂了，去找一檔股票</button>';$('#learn-view').prepend(quiz);quiz.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>{$('#quiz-answer').textContent=b.dataset.quiz==='later'?'答對了。進階委託等待後續收盤；快速練習則用已取得收盤建立持倉，兩種都可在虛擬投資查看。':'進階委託還沒成交，必須等委託日之後第一筆交易日收盤，並符合你設定的價格。';});$('#learn-start').onclick=()=>switchTab('market');
